package clusterdata.datatypes;

import java.io.Serializable;

/**
 * Represents a task event from the Google cluster trace.
 *
 * Fields correspond to the columns in the task_events CSV:
 * 1. time (microseconds)
 * 2. missing_info
 * 3. job_id
 * 4. task_index
 * 5. machine_id
 * 6. event_type (0=submit, 1=schedule, 2=evict, 3=fail, 4=finish, 5=kill, 6=lost, 7=update_pending, 8=update_running)
 * 7. user
 * 8. scheduling_class
 * 9. priority
 * 10. cpu_request
 * 11. memory_request
 * 12. disk_space_request
 * 13. different_machines_restriction
 */
public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    public long time;  // timestamp in microseconds
    public String missing_info;
    public long job_id;
    public long task_index;
    public long machine_id;
    public int event_type;
    public String user;
    public int scheduling_class;
    public int priority;
    public double cpu_request;
    public double memory_request;
    public double disk_space_request;
    public int different_machines_restriction;

    public TaskEvent() {
    }

    public TaskEvent(long time, String missing_info, long job_id, long task_index,
                     long machine_id, int event_type, String user, int scheduling_class,
                     int priority, double cpu_request, double memory_request,
                     double disk_space_request, int different_machines_restriction) {
        this.time = time;
        this.missing_info = missing_info;
        this.job_id = job_id;
        this.task_index = task_index;
        this.machine_id = machine_id;
        this.event_type = event_type;
        this.user = user;
        this.scheduling_class = scheduling_class;
        this.priority = priority;
        this.cpu_request = cpu_request;
        this.memory_request = memory_request;
        this.disk_space_request = disk_space_request;
        this.different_machines_restriction = different_machines_restriction;
    }

    /**
     * Parse a TaskEvent from a CSV line.
     */
    public static TaskEvent parse(String line) {
        String[] fields = line.split(",");
        if (fields.length < 13) {
            return null;
        }

        try {
            TaskEvent event = new TaskEvent();
            event.time = Long.parseLong(fields[0]);
            event.missing_info = fields[1];
            event.job_id = Long.parseLong(fields[2]);
            event.task_index = Long.parseLong(fields[3]);
            event.machine_id = fields[4].isEmpty() ? 0 : Long.parseLong(fields[4]);
            event.event_type = Integer.parseInt(fields[5]);
            event.user = fields[6];
            event.scheduling_class = Integer.parseInt(fields[7]);
            event.priority = Integer.parseInt(fields[8]);
            event.cpu_request = Double.parseDouble(fields[9]);
            event.memory_request = Double.parseDouble(fields[10]);
            event.disk_space_request = Double.parseDouble(fields[11]);
            event.different_machines_restriction = Integer.parseInt(fields[12]);
            return event;
        } catch (Exception e) {
            return null;
        }
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "time=" + time +
                ", job_id=" + job_id +
                ", task_index=" + task_index +
                ", event_type=" + event_type +
                '}';
    }
}

