     */
    public static class JobStageProcessor extends RichMapFunction<TaskEvent, Tuple2<Long, Integer>> {
        private long sessionGapMicros;
        private transient Map<Long, JobStageInfo> jobStages;

        public JobStageProcessor(long sessionGapMicros) {
            this.sessionGapMicros = sessionGapMicros;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            super.open(parameters);
            jobStages = new HashMap<>();
        }

